//! Deterministic generated contracts; no dependency on checked-in generated files.
use crate::types::*;
use schemars::{JsonSchema, generate::SchemaSettings};
use serde_json::{Value, json};
use ts_rs::{Config, TS};

pub fn schema<T: JsonSchema>() -> Value {
    let root = SchemaSettings::draft2020_12()
        .into_generator()
        .into_root_schema_for::<T>();
    serde_json::to_value(root).expect("schema serialization")
}

pub fn typescript() -> String {
    let config = Config::default();
    let mut output =
        String::from("// Generated by cargo run -p xtask -- generate. Do not edit.\n\n");
    macro_rules! declarations {
        ($($ty:ty),* $(,)?) => { $(output.push_str("export ");
            output.push_str(&<$ty>::decl(&config)); output.push_str("\n\n");)* };
    }
    declarations!(
        ProtocolVersion,
        TickRate,
        SnapshotRate,
        EntityId,
        VisibilityId,
        ControlEpoch,
        BaselineId,
        RequestId,
        EventId,
        Revision,
        Credits,
        TshirtColour,
        InputAxis,
        Buttons,
        Heat,
        Magazine,
        InputLead,
        EntityCount,
        CharacterHealth,
        VehicleHealth,
        Yaw,
        Pitch,
        Steering,
        Scalar,
        Severity,
        Milliseconds,
        OpaqueId,
        BuildId,
        TemplateId,
        ContentHash,
        DisplayName,
        ChatText,
        ChatLine,
        DetailText,
        Vec3,
        Empty,
        ClientEnvelope,
        ServerEnvelope,
        ClientMessage,
        ClientHello,
        ClientReady,
        InputBatch,
        InputFrame,
        ActionRequest,
        Trigger,
        Action,
        EnterVehicle,
        Fire,
        AcceptMission,
        Repair,
        Ping,
        ResyncRequest,
        ResyncReason,
        Delivery,
        ServerMessage,
        ServerHello,
        Reject,
        RejectCode,
        Welcome,
        ProfileView,
        BaselineBegin,
        EntityShow,
        BaselineEnd,
        StartPlay,
        EntityHide,
        HideReason,
        Snapshot,
        EntityDescriptor,
        EntityKind,
        CharacterMotor,
        VehicleMotor,
        CharacterState,
        VehicleState,
        CharacterMode,
        EntityState,
        StateRecord,
        OwnerState,
        ActionResult,
        ActionCode,
        MissionView,
        MissionPhase,
        PlayerStatus,
        RepairView,
        RepairPhase,
        Pursuit,
        WorldEvent,
        Shot,
        WeaponId,
        WeaponDefinition,
        WeaponSlotView,
        EquipmentView,
        EquipWeapon,
        Impact,
        Pong,
        Disconnect,
    );
    output.push_str(&format!(
        "export type Tick = {};\n",
        <Tick>::inline(&config)
    ));
    output
}

pub fn limits() -> Value {
    use crate::limits::*;
    json!({
        "client_bytes": CLIENT_BYTES, "reliable_bytes": RELIABLE_BYTES,
        "unreliable_bytes": UNRELIABLE_BYTES, "max_depth": MAX_DEPTH,
        "max_string_bytes": MAX_STRING_BYTES,
        "max_map_fields": MAX_MAP_FIELDS, "max_array_items": MAX_ARRAY_ITEMS,
        "max_input_frames": MAX_INPUT_FRAMES, "max_visible_entities": MAX_VISIBLE_ENTITIES,
        "max_safe_integer": MAX_SAFE_INTEGER, "max_float": f64::from(f32::MAX)
    })
}
